// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

contract FirmwareRegistry {
    struct FirmwareInfo {
        string version;      // e.g. "0x0102"
        bytes32 hash;        // SHA-256 hash of the firmware
        string cid;          // IPFS CID
        bytes signature;     // Digital signature (DER-encoded)
        uint256 timestamp;   // When this firmware was published
        string deviceType;   // New field: device line / chip family
    }

    // Map from firmware version => FirmwareInfo
    mapping(string => FirmwareInfo) public firmwareByVersion;

    // Updated event to include deviceType
    event FirmwarePublished(
        string version,
        bytes32 hash,
        string cid,
        bytes signature,
        uint256 timestamp,
        string deviceType
    );

    /**
     * @notice Publishes firmware metadata to the registry.
     * @param _version The firmware version (string).
     * @param _hash The SHA-256 hash of the firmware (bytes32).
     * @param _cid The IPFS CID pointing to the firmware file (string).
     * @param _signature The digital signature of the firmware (bytes).
     * @param _deviceType The device line or chip family (string).
     */
    function publishFirmware(
        string memory _version,
        bytes32 _hash,
        string memory _cid,
        bytes memory _signature,
        string memory _deviceType
    ) public {
        // Build a new FirmwareInfo struct in memory
        FirmwareInfo memory info = FirmwareInfo({
            version: _version,
            hash: _hash,
            cid: _cid,
            signature: _signature,
            timestamp: block.timestamp,
            deviceType: _deviceType
        });

        // Store in the mapping, keyed by firmware version
        firmwareByVersion[_version] = info;

        // Emit an event so off-chain services can listen for new firmware
        emit FirmwarePublished(
            _version,
            _hash,
            _cid,
            _signature,
            block.timestamp,
            _deviceType
        );
    }
}

